    private static final int INVROOT = 469870224;

    private static int reverseBits(int n, int k) {
        return Integer.reverse(n) >>> (32 - k);
    }

    private static long modularInverse(int a) {
        return modularExponentiation(a, MOD - 2);
    }

    private static long modularExponentiation(int a, int p) {
        if (p == 0) {
            return 1;
        }
        long halfPower = modularExponentiation(a, p / 2);
        long result = (halfPower * halfPower) % MOD;
        if (p % 2 == 1) {
            result = (result * a) % MOD;
        }
        return result;
