#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int ROOT = 15311432;
const int INVROOT = 469870224;

int reverseBits(int n, int k) {
    int res = 0;
    for (int i = 0; i < k; i++) {
        res = (res << 1) | (n & 1);
        n >>= 1;
    }
    return res;
}

long long modularInverse(int a) {
    return modularExponentiation(a, MOD - 2);
}

long long modularExponentiation(long long a, long long p) {
    long long result = 1;
    long long base = a % MOD;
    while (p > 0) {
        if (p & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        p >>= 1;
    }
    return result;
}

void performNTT(std::vector<long long>& coefficients, int logSize, bool inverseTransform) {
    int size = coefficients.size();
    int baseRoot = inverseTransform ? INVROOT : ROOT;
    long long root = modularExponentiation(baseRoot, (1 << (23 - logSize)));
    std::vector<long long> roots(logSize);
    roots[logSize - 1] = root;
    for (int i = logSize - 1; i > 0; i--) {
        roots[i - 1] = (roots[i] * roots[i]) % MOD;
    }
    for (int s = 0; s < logSize; s++) {
        int segmentLength = 1 << s;
        for (int start = 0; start < size; start += 2 * segmentLength) {
            long long currentRoot = 1;
            for (int j = start; j < start + segmentLength; j++) {
                long long temp = (currentRoot * coefficients[j + segmentLength]) % MOD;
                long long u = coefficients[j];
                coefficients[j] = (u + temp) % MOD;
                coefficients[j + segmentLength] = (u - temp + MOD) % MOD;
                currentRoot = (roots[s] * currentRoot) % MOD;
            }
        }
    }
    if (inverseTransform) {
        long long invSize = modularInverse(size);
        for (int i = 0; i < size; i++) {
            coefficients[i] = (coefficients[i] * invSize) % MOD;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n_input, m;
    cin >> n_input >> m;
    int n = n_input / 2;
    vector<int> numbers(m);
    for (int i = 0; i < m; i++) {
        cin >> numbers[i];
    }
    sort(numbers.begin(), numbers.end());
    int minSize = n * numbers[m - 1] + 2;
    int logSize = 0;
    int size = 1;
    while (size < minSize) {
        size <<= 1;
        logSize++;
    }
    vector<long long> array(size, 0);
    for (int num : numbers) {
        array[reverseBits(num, logSize)] = 1;
    }
    performNTT(array, logSize, false);
    for (int i = 0; i < size; i++) {
        array[i] = modularExponentiation(array[i], n);
    }
    vector<long long> tempArray(size, 0);
    for (int i = 0; i < size; i++) {
        tempArray[reverseBits(i, logSize)] = array[i] % MOD;
    }
    array = tempArray;
    performNTT(array, logSize, true);
    long long total = 0;
    for (int i = 0; i < size; i++) {
        total = (total + array[i] * array[i]) % MOD;
    }
    long long invSize = modularInverse(size);
    cout << (((total * invSize) % MOD) * invSize) % MOD << "\n";
    return 0;
}
